#!/usr/bin/env bash\nset -e\n\n# Mock rationale: using local init, no AWS calls.\n\n# Initialize Terraform without a remote backend\nterraform init -backend=false > /dev/null\n\n# Validate the configuration syntax\nterraform validate\n\n# Perform a dry‑run plan with a static bucket name\nterraform plan -input=false -var 'bucket_name=apocalypse-safehouse-test' -out=plan.out > /dev/null\n\necho \"All tests passed.\"
